 [match(('Issues and responses','ጉዳዮችና ምላሾች'),('Global problems need local and global action.','ዓለም አቀፍ ችግሮች የአካባቢና የዓለም አቀፍ እርምጃ ይፈልጋሉ።'),[[(('Climate change','የአየር ንብረት ለውጥ'),('plant trees, use clean energy','ዛፍ መትከል፣ ንጹህ ኃይል መጠቀም')),(('Rapid population growth','ፈጣን የሕዝብ እድገት'),('education, health and family planning','ትምህርት፣ ጤናና የቤተሰብ ምጣኔ')),(('Human trafficking','ሕገ ወጥ የሰዎች ዝውውር'),('awareness and legal migration','ግንዛቤና ሕጋዊ ስደት'))],[(('Terrorism','ሽብርተኝነት'),('cooperation, tolerance, reporting threats','ትብብር፣ መቻቻል፣ ስጋትን ማሳወቅ')),(('HIV/AIDS','ኤች.አይ.ቪ/ኤድስ'),('prevention, testing, ending stigma','መከላከል፣ ምርመራ፣ መገለልን ማስቆም')),(('Land degradation','የመሬት መራቆት'),('terracing and reforestation','እርከንና መልሶ ማልማት'))]]),
  quiz(('Stay informed and safe','ተገንዘቡ፣ ደህና ሁኑ'),('Human traffickers often promise easy jobs abroad. Check offers with family and official agencies before travelling.','ሕገ ወጥ አዘዋዋሪዎች ብዙ ጊዜ በውጭ አገር ቀላል ሥራ ቃል ይገባሉ። ከመጓዝ በፊት አቅርቦቶችን ከቤተሰብና ከሕጋዊ ተቋማት ጋር አረጋግጡ።'),[
   q('A stranger offers a high-paid job abroad with no papers needed. This may be…','የማታውቁት ሰው ያለ ሰነድ በውጭ አገር ከፍተኛ ደመወዝ ያለው ሥራ ቃል ገባ። ይህ ሊሆን የሚችለው…',[('human trafficking','ሕገ ወጥ የሰዎች ዝውውር'),('a safe opportunity','ደህና ዕድል')]),
   q('A main cause of climate change is…','የአየር ንብረት ለውጥ ዋና ምክንያት…',[('greenhouse gases from burning fuels and deforestation','ከነዳጅ ማቃጠልና ከደን ጭፍጨፋ የሚወጡ የሙቀት አማቂ ጋዞች'),('planting trees','ዛፍ መትከል')]),
   q('People living with HIV should be treated with…','ከኤች.አይ.ቪ ጋር የሚኖሩ ሰዎች መያዝ ያለባቸው…',[('respect and support','በክብርና በድጋፍ'),('fear and exclusion','በፍርሃትና በማግለል')]),
   q('Rapid population growth can strain…','ፈጣን የሕዝብ እድገት… ላይ ጫና ያሳድራል',[('land, water, schools and jobs','መሬት፣ ውኃ፣ ትምህርት ቤትና ሥራ'),('nothing','ምንም')])])],
